    if (!title) {
      html(res, 400, projectPage(project, filter, '', '', { id: task.id, message: 'Task title is required' }));
      return;
    }
    renameTask.run(title, task.id, project.id);
    res.writeHead(303, { Location: `/projects/${project.id}?filter=${filter}` });
    res.end();
    return;
  }
}
